example:
- id: AGT-014
  title: Decision record per autonomous action
  applies_to: {tier: ">=T3"}
  test: records.count(agent, period) == actions.count(agent, period)
  evidence: {record: decision_record, field: record_id}
  on_fail: block_deploy
  maps_to: [AICM GOV-07, ISO42001 A.6.2.8, AIAct Art.12]
- id: AGT-022
  title: Grounds stated in structured fields
  applies_to: {tier: ">=T2", decision_class: closure}
  test: all(record.grounds[f] is not null for f in required_fields)
  evidence: {record: decision_record, field: grounds}
  on_fail: block_action
